import math
def control(obs):
    h=obs['hitch_deg']
    pts=[]
    view=obs.get('views',{}).get('direct') or {}
    ox,oy=view.get('origin',[0.75,0])
    for b,d in view.get('walls',[]):
        x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
        if -13<x<-6 and 0<y<9: pts.append((x,y))
    if pts:
        y=sum(p[1] for p in pts)/len(pts)
        desired=max(-10,min(10,(y-3.2)*3))
    else: desired=0
    return (max(-30,min(30,2.3*(h-desired))),-0.6,170)

